let storageAvailable=true;
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORE_KEY));if(saved?.schema===1 && saved.patients?.length && Array.isArray(saved.cases)&&Array.isArray(saved.records)&&Array.isArray(saved.reports)&&Array.isArray(saved.messages)&&Array.isArray(saved.events)&&Array.isArray(saved.visits))return saved;}catch{}return seedState();}
