const caseDrafts=new Map();
function rememberCaseDraft(){if(modalContext.kind==='case'&&document.getElementById('case-note'))caseDrafts.set(modalContext.id,{note:read('case-note'),status:read('case-status'),review:checked('case-review')});}
function restoreCaseDraft(){const draft=caseDrafts.get(modalContext.id);if(!draft||!document.getElementById('case-note'))return;document.getElementById('case-note').value=draft.note;document.getElementById('case-status').value=draft.status;if(document.getElementById('case-review'))document.getElementById('case-review').checked=draft.review;}
function persist(){try{localStorage.setItem(STORE_KEY,JSON.stringify(state));}catch{storageAvailable=false;}render();}
function addEvent(text){state.events.unshift({time:timeLabel(),text});state.events=state.events.slice(0,30);}
function addMessage(pid,title,text,source='医护确认',author=currentClinician,metadata={}){state.messages.unshift({id:uuid('message'),pid,title,text,source,author,...metadata,time:`10-08 ${timeLabel()}`,read:false});}
function patientCases(pid){return state.cases.filter(item=>item.pid===pid);}
function patientRecords(pid){return state.records.filter(record=>record.pid===pid);}
function openCases(pid){return state.cases.filter(item=>item.status!=='已关闭'&&(!pid||item.pid===pid));}
function addCase(pid,type,level,title,detail,source='患者自报'){
  const existing=openCases(pid).find(item=>item.type===type);
  if(existing){existing.audit.push({time:`10-08 ${timeLabel()}`,text:`新增反馈：${detail}`});if(level==='high'){existing.level='high';existing.deadline='优先接管 · 演示';}return existing;}
  const item={id:uuid('case'),pid,type,level,status:'待处理',owner:'待认领',title,detail,source,created:`10-08 ${timeLabel()}`,deadline:level==='high'?'优先接管 · 演示':'本服务日内 · 演示',audit:[{time:`10-08 ${timeLabel()}`,text:`${source}：${detail}`}]};
  state.cases.unshift(item);return item;
}
function addRecord(pid,type,title,detail,status='已完成',source='患者确认'){
  const patient=patientById(pid);
  const slot=ui.role==='patient'&&ui.patientPage==='task'&&ui.task?.type===type?taskSlot():null;
  state.records.unshift({id:uuid('record'),pid,type,title:slot?`${slot.label} · ${title}`:title,detail,status,source,date:TODAY,time:timeLabel(),version:patientHasPublishedPlan(patient)?patient.plan.version:0,...(slot?{slot:slot.id}: {})});
  addEvent(`${patient.name} · ${title}`);
}
function taskDone(patient,type){if(type==='training'&&configuredTrainingDeferred(patient))return false;if(type==='training'&&legacyTrainingDone(patient))return true;if(type==='training'||type==='nutrition')return taskSlots(patient,type).every(slot=>slotDone(patient,type,slot.id));return state.records.some(record=>record.pid===patient.id&&record.type===type&&record.date===TODAY&&record.status==='已完成');}
function enabledTasks(patient){if(!patientHasPublishedPlan(patient)||!cycleIsActive(patient))return [];return Object.keys(serviceTypes).filter(type=>patient.plan[type]);}
function completedToday(patient){return enabledTasks(patient).filter(type=>taskDone(patient,type)).length;}
function toast(message){const target=document.getElementById('toast');target.textContent=message;target.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>target.classList.remove('show'),3500);}
