function metric(label,value,unit,graphic,foot,tone=''){return `<div class="metric ${tone}"><div class="between"><label>${label}</label><span class="metric-icon">${icon(graphic)}</span></div><div class="metric-number">${value}<span>${unit}</span></div><div class="metric-foot">${foot}</div></div>`;}
function caseTable(){
  let items=state.cases.filter(item=>ui.filter==='closed'?item.status==='已关闭':item.status!=='已关闭');
  if(ui.filter==='high')items=items.filter(item=>item.level==='high');
  if(ui.filter==='progress')items=items.filter(item=>['跟进中','待患者补充','待复诊'].includes(item.status));
  if(ui.search.trim())items=items.filter(item=>`${patientById(item.pid)?.name} ${item.title} ${item.type}`.includes(ui.search.trim()));
  items.sort((left,right)=>({high:0,medium:1,normal:2}[left.level]-{high:0,medium:1,normal:2}[right.level]));
  return `${items.length?`<div class="table-wrap"><table><thead><tr><th>患者 / 服务路径</th><th>关注事项</th><th>状态 / 负责人</th><th>操作</th></tr></thead><tbody>${items.map(item=>{const patient=patientById(item.pid);return `<tr class="${item.status==='已关闭'?'row-closed':''}"><td><div class="patient-cell">${avatar(patient)}<div><strong>${escapeHtml(patient.name)}</strong><small>${escapeHtml(patient.path)} · 第 ${patient.day} 天</small></div></div></td><td>${sourceTag(item.type,item.level==='high'?'red':item.level==='medium'?'orange':'blue')}<small>${escapeHtml(item.deadline)}</small></td><td><strong>${escapeHtml(item.status)}</strong><small>${escapeHtml(item.owner)}</small></td><td><button class="table-action" data-action="case" data-id="${item.id}">${item.status==='已关闭'?'查看记录':'查看处理'} →</button></td></tr>`;}).join('')}</tbody></table></div>`:`<div class="empty">${icon('check')}<p>这里暂无匹配事项</p><small>可以切换筛选，或到患者端提交新反馈。</small></div>`}<div class="table-footer"><span>共 ${items.length} 项 · 高优先级事项必须人工复核</span><span>单页展示</span></div>`;
}
function historyChart(patient){const values=[...(patient.history||[0,0,0,0,0,0]),completedToday(patient)];const max=Math.max(enabledTasks(patient).length,...values,1);return `<div class="chart">${values.map((value,index)=>`<div class="chart-col ${index===6?'current':''}"><b>${value}</b><span style="height:${Math.max(4,value/max*74)}px"></span><label>${index===6?'今天':`10.${String(index+2).padStart(2,'0')}`}</label></div>`).join('')}</div>`;}
function renderPatients(){return `<div class="page-title between"><div><div class="eyebrow" style="margin-bottom:9px">PATIENT DIRECTORY</div><h1>每一位患者，一份持续的关心</h1><p>服务档案关联阶段计划、执行记录与负责团队。</p></div><button class="btn primary" data-action="enroll">${icon('plus')}建立服务档案</button></div><div class="patient-roster">${state.patients.map(patient=>{const published=patientHasPublishedPlan(patient);return `<section class="panel roster-card"><div class="between"><div class="flex">${avatar(patient)}<div><h3>${escapeHtml(patient.name)}</h3><small>${patient.age} 岁 · ${patient.gender} · 演示患者</small></div></div>${sourceTag('在管','green')}</div><p>${escapeHtml(patient.procedure)}<br>${escapeHtml(patient.team)}</p><div class="between" style="margin-bottom:20px"><small>计划 ${planVersionLabel(patient)}${published?` · 第 ${patient.day} 天`:''}</small>${sourceTag(published?'计划已发布':'待建立计划',published?'green':'orange')}</div><button class="btn" data-action="patient-detail" data-id="${patient.id}">查看服务档案 ${icon('arrow')}</button></section>`;}).join('')}</div>`;}
function renderPlans(){return `<div class="page-title"><div class="eyebrow" style="margin-bottom:9px">CARE PLANS</div><h1>专业计划，落实到每一天</h1><p>计划调整由当前授权医护确认发布；历史执行记录始终绑定当时版本。</p></div><div class="notice">${icon('shield')} 这里是产品演示计划，不是医疗处方。动作、阈值、频次和服务周期均需院方审核后上线。</div><div class="plan-list">${state.patients.map(patient=>{const published=patientHasPublishedPlan(patient),cycle=published?cycleFor(patient):null;return `<section class="panel plan-card"><div class="flex">${avatar(patient)}<div><h3>${escapeHtml(patient.name)} ${sourceTag(planVersionLabel(patient),published?'green':'orange')}</h3><p>${escapeHtml(patient.procedure)}</p></div></div><div>${published?`<h3>${escapeHtml(patient.plan.stage)}</h3><p>${escapeHtml(cycle.kind)}：${displayDate(cycle.start)} — ${displayDate(patient.plan.end)}<br>${cycle.reviewEvery?`每 ${cycle.reviewEvery} 天回访`:'回访频率待设置'} · 本版本 ${displayDate(patient.plan.start)} 生效</p><div class="plan-tasks">${enabledTasks(patient).map(type=>sourceTag(serviceTypes[type])).join('')}</div>`:'<h3>服务档案已建立，等待医护设置计划</h3><p>尚未发布 V1，患者端暂不派发康复训练、饮食记录或恢复随访任务。</p>'}</div><button class="btn ${published?'':'primary'}" data-action="plan" data-id="${patient.id}">${published?'查看 / 调整计划':'建立阶段计划'}</button></section>`;}).join('')}</div>`;}
function renderReports(){return `<div class="page-title"><div class="eyebrow" style="margin-bottom:9px">WEEKLY CARE SUMMARY</div><h1>带着一周的记录，见下一次面</h1><p>周报汇总执行与处置，不输出诊断；新记录不会悄悄改写已生成的周报。</p></div><div class="patient-roster">${state.patients.map(patient=>{const report=state.reports.find(item=>item.pid===patient.id);return `<section class="panel roster-card"><div class="flex">${avatar(patient)}<div><h3>${escapeHtml(patient.name)}</h3><small>10.02 — 10.08 · 演示周</small></div></div>${historyChart(patient)}<div class="mini-row"><span>未解决事项</span>${sourceTag(`${openCases(patient.id).length} 项`,'orange')}</div><p>${report?`最新快照：${escapeHtml(report.created)}<br>${report.reviewed?'已由医护复核':'AI整理草稿 · 尚待医护复核'}`:'尚未生成周报<br>生成前可先处理待办与核实记录。'}</p><button class="btn primary" data-action="report" data-id="${patient.id}">${report?'查看 / 更新周报':'生成周报预览'}</button></section>`;}).join('')}</div>`;}
function patientShell(){const patient=activePatient(),published=patientHasPublishedPlan(patient),pending=openCases(patient.id),complete=completedToday(patient),pageView=!published&&!['messages','mine','feedback','shop','shopProduct','shopOrders','shopOrder'].includes(ui.patientPage)?patientNoPlan:({home:patientHome,task:patientTaskPage,feedback:patientFeedbackPage,cycle:patientCycle,progress:patientProgress,messages:patientMessages,mine:patientMine,shop:patientShop,shopProduct:shopProductPage,shopOrders:patientShopOrders,shopOrder:shopOrderPage}[ui.patientPage]||patientHome);return `<div class="patient-layout"><div class="phone-wrap"><div class="phone-caption"><span>患者端 App · 交互模拟</span><button class="link" data-action="switch-patient">${escapeHtml(patient.name)} ⇄</button></div><section class="phone"><div class="phone-status"><span>09:41</span><div class="flex">${icon('signal')}${icon('battery')}</div></div><header class="phone-head"><div class="brand"><span class="brand-symbol">${icon('heart')}</span><div><strong>新华在家</strong><small>离院不断服务，回家仍有新华</small></div></div><button class="icon-btn" aria-label="服务说明" data-action="service">${icon('shield')}</button></header><div class="phone-body">${pageView(patient)}</div><nav class="phone-nav">${[['home','home','今日'],['cycle','list','计划'],['progress','chart','进度'],['messages','chat','消息'],['shop','food','商城'],['mine','user','我的']].map(([key,graphic,label])=>`<button class="${(ui.patientPage===key||(key==='shop'&&ui.patientPage.startsWith('shop')))?'active':''}" data-action="patient-page" data-value="${key}">${icon(graphic)}${label}${key==='messages'&&state.messages.some(message=>message.pid===patient.id&&!message.read)?'<span class="unread"></span>':''}</button>`).join('')}</nav></section></div><aside class="journey-aside"><div class="eyebrow">ONE PLAN. CONTINUOUS CARE.</div><h1>回家以后，<br>每一步都有照应。</h1><p>患者的每一次记录，连接医护的下一次跟进。<br>在这里体验一条有回应、有处置的居家恢复路径。</p><div class="journey-path">${journeyStep(1,'服务已建立',`${patient.team} · ${published?`当前计划 ${planVersionLabel(patient)}`:'档案已建立，待设置计划'}`, 'done')}${journeyStep(2,'完成今日小任务',published?`${complete} / ${enabledTasks(patient).length} 项已完成，记录来自患者确认。`:'计划发布后开始派发任务。',published&&complete?'done':'active')}${journeyStep(3,'有需要，团队接住',`${pending.length} 项待跟进。紧急情况不等待线上回复。`,pending.length?'active':'')}${journeyStep(4,'带着记录去复诊',`复诊日期：${displayDate(patient.appointment)}；周报可供医护复核。`,'')}</div><section class="journey-summary"><div class="between"><h3>双端联动预览</h3>${sourceTag('本地保存','green')}</div><div class="mini-row"><span>当前患者</span><strong>${escapeHtml(patient.name)} · ${planVersionLabel(patient)}</strong></div><div class="mini-row"><span>本次演示新增记录</span><strong>${patientRecords(patient.id).length} 条</strong></div><div class="mini-row"><span>医护待处理事项</span><strong>${pending.length} 项</strong></div><button class="btn block" style="margin-top:12px" data-action="role" data-value="doctor">去工作台查看并处理 ${icon('arrow')}</button></section><p style="font-size:10px;line-height:1.9;color:#a1ad9a;margin-top:16px">演示提示：可从训练不适或恢复问答产生事项。<br>不调用相机、麦克风或 AI 服务；日期固定为 2026.10.08。</p></aside></div>`;}
function journeyStep(number,title,detail,status){return `<div class="journey-step ${status}"><span class="step-num">${status==='done'?icon('check'):number}</span><div><strong>${title}</strong><p>${escapeHtml(detail)}</p></div></div>`;}
function patientHome(patient){
  if(!patientHasPublishedPlan(patient))return patientNoPlan(patient);
  const tasks=enabledTasks(patient),complete=completedToday(patient),cycle=cycleFor(patient),active=cycleIsActive(patient);
  return `<div class="greeting"><div class="flex">${avatar(patient)}<div><h2>${escapeHtml(patient.name)}，你好</h2><p>今天是 10 月 8 日，按自己的节奏慢慢来。</p></div></div></div>${clinicianFeedbackBanner(patient)}${cycleHomeLink(patient)}<section class="recovery-card"><span class="eyebrow">YOUR DAILY CARE</span><h3>${escapeHtml(patient.plan.stage)}</h3><p>${active?'按医护确认的安排完成今日记录。':TODAY<cycle.start?'当前周期尚未开始，暂不派发任务。':'本周期已结束，等待医护评估后续安排。'}</p><div class="progress-track"><span style="width:${tasks.length?complete/tasks.length*100:0}%"></span></div><p>今日已完成 ${complete} / ${tasks.length} 项 · ${planVersionLabel(patient)}</p></section><div class="phone-section-title"><h3>今日小任务</h3><small>医护设置 · 患者确认</small></div>${tasks.map(type=>{const done=taskDone(patient,type),slots=taskSlots(patient,type),detail=type==='training'?configuredTrainingDeferred(patient)?'今日已有旧版记录，新版训练明日起执行':`${slots.length} 项训练安排 · 查看动作与组次`:type==='nutrition'?'早餐、午餐、晚餐 · 分餐记录':'每日一次 · 反馈恢复情况与执行困难';return `<button class="task-card" data-action="task" data-value="${type}"><span class="task-icon ${type==='nutrition'?'food':type==='survey'?'survey':''}">${icon(type==='training'?'training':type==='nutrition'?'food':'chat')}</span><div><h3>${serviceTypes[type]}${done?' · 已记录':''}</h3><p>${detail}</p></div><span class="arrow">${icon('arrow')}</span></button>`;}).join('')||'<p class="task-hint">当前没有待执行任务，有问题仍可联系服务团队。</p>'}<div class="phone-help"><span style="color:#829c72">${icon('chat')}</span><div><h3>有问题，不用一个人琢磨</h3><p>提问或反馈不适，团队会人工跟进。</p></div><button class="icon-btn" aria-label="提问或反馈不适" data-action="ask">${icon('arrow')}</button></div><div class="phone-disclaimer">服务时段：工作日 08:00—17:00（演示）<br>紧急情况请及时就医，不要等待线上回复。</div>`;
}
function patientNoPlan(patient){return `<div class="greeting"><div class="flex">${avatar(patient)}<div><h2>${escapeHtml(patient.name)}，你好</h2><p>服务档案已经建立，计划会由医护团队继续准备。</p></div></div></div>${clinicianFeedbackBanner(patient)}<section class="empty-plan-card"><span class="task-icon">${icon('clock')}</span><div><span class="eyebrow">SERVICE PROFILE READY</span><h2>等待医护设置阶段计划</h2><p>${escapeHtml(patient.procedure)} · ${escapeHtml(patient.team)}</p><p>当前还没有发布 V1 计划，所以不会派发康复训练、饮食记录或恢复随访任务。计划发布后，你会在这里看到长期周期和每天的小任务。</p></div></section><div class="phone-help"><span style="color:#829c72">${icon('chat')}</span><div><h3>有问题，不用一个人琢磨</h3><p>现在也可以提问或反馈不适，团队会人工跟进。</p></div><button class="icon-btn" aria-label="提问或反馈不适" data-action="ask">${icon('arrow')}</button></div><div class="phone-disclaimer">服务时段：工作日 08:00—17:00（演示）<br>紧急情况请及时就医，不要等待线上回复。</div>`;}
function patientProgress(patient){const records=patientRecords(patient.id);return `<div class="phone-page-title"><h2>每一步，都被记下</h2><p>执行记录与周报，为下一次复诊做好准备。</p></div><div class="report-hero"><span class="eyebrow">WEEKLY SUMMARY</span><h2>我的恢复周报</h2><p>10 月 2 日 — 10 月 8 日<br>记录进展，不替代医护评估。</p><div class="report-grid"><div><strong>${records.length}</strong><small>新增记录</small></div><div><strong>${openCases(patient.id).length}</strong><small>跟进事项</small></div><div><strong>${planVersionLabel(patient)}</strong><small>当前计划</small></div></div><button class="btn block" style="margin-top:20px" data-action="patient-report" data-id="${patient.id}">查看本周摘要 ${icon('arrow')}</button></div><div class="phone-section-title"><h3>今天的记录</h3><small>按提交时间排序</small></div>${records.length?records.map(record=>`<div class="record-item"><div class="between"><h3>${escapeHtml(record.title)}</h3>${sourceTag(record.status,record.status==='已完成'?'green':'orange')}</div><p>${escapeHtml(record.detail)}</p><div class="between" style="margin-top:10px"><small>${record.time} · ${record.version?'计划 V'+record.version:'建档阶段'}</small><small>${escapeHtml(record.source)}</small></div></div>`).join(''):'<div class="empty">完成今天的任务后，记录会出现在这里。<br><small>未记录不代表恢复正常。</small></div>'}`;}
function patientMessages(patient){const messages=state.messages.filter(message=>message.pid===patient.id);return `<div class="phone-page-title"><h2>来自团队的关心</h2><p>医护回复、计划变化与复诊安排都在这里。</p></div>${patientFollowUps(patient)}${messages.map(message=>`<article class="message-card"><div class="between"><div class="flex"><span class="avatar">${message.source==='医护确认'?'医':'助'}</span><strong>${escapeHtml(message.author)}</strong></div>${sourceTag(message.source,message.source==='医护确认'?'green':'blue')}</div><h3 style="margin-top:15px">${escapeHtml(message.title)}</h3><p>${escapeHtml(message.text)}</p><small>${escapeHtml(message.time)} ${message.read?'· 已读':''}</small></article>`).join('')||'<div class="empty">暂无新消息</div>'}<button class="btn block" data-action="ask">${icon('chat')}提问 / 反馈不适</button>`;}
function patientMine(patient){const published=patientHasPublishedPlan(patient);return `<div class="phone-page-title"><div class="flex">${avatar(patient)}<div><h2>${escapeHtml(patient.name)}</h2><p>${patient.age} 岁 · 本人使用 · 虚构档案</p></div></div></div><div class="message-card"><h3>我的服务团队</h3><p>${escapeHtml(patient.team)}<br>工作日 08:00 — 17:00（演示）</p>${sourceTag('当前服务中','green')}</div><button class="task-card" data-action="view-plan" data-id="${patient.id}"><span class="task-icon">${icon('list')}</span><div><h3>我的阶段计划</h3><p>${published?`${planVersionLabel(patient)} · ${escapeHtml(patient.plan.author)}已确认`:'尚未发布 · 等待医护设置'}</p></div><span class="arrow">${icon('arrow')}</span></button><button class="task-card" data-action="appointment-info" data-id="${patient.id}"><span class="task-icon survey">${icon('clock')}</span><div><h3>下次复诊</h3><p>${displayDate(patient.appointment)} · 模拟安排</p></div><span class="arrow">${icon('arrow')}</span></button><button class="task-card" data-action="service"><span class="task-icon">${icon('shield')}</span><div><h3>服务范围与数据说明</h3><p>AI辅助边界 · 授权 · 家属代办</p></div><span class="arrow">${icon('arrow')}</span></button>${shopMineLinks()}<div class="phone-disclaimer">此原型未采集真实身份、照片或健康信息。<br>请勿录入真实患者资料。</div>`;}
function patientFollowUps(patient){return openCases(patient.id).map(item=>`<article class="message-card"><div class="between"><h3>${escapeHtml(item.type)}</h3>${sourceTag(item.status,item.level==='high'?'red':'orange')}</div><p>${escapeHtml(item.resolution||'反馈已登记，等待团队进一步了解。')}</p><small>负责人：${escapeHtml(item.owner)} · 不是实时急救通道</small><button class="btn block" style="margin-top:12px" data-action="reply-case" data-id="${item.id}">${item.status==='待患者补充'?'补充团队需要的信息':'补充情况 / 查看跟进'}</button></article>`).join('');}
function replyCase(id){
  const item=state.cases.find(entry=>entry.id===id);
  if(!item||item.pid!==activePatient().id||item.status==='已关闭')return;
  modalContext={kind:'reply',id};
  showModal('补充恢复情况',`${escapeHtml(item.type)} · 继续同一事项，不重复建单`, `<div class="notice blue">${escapeHtml(item.resolution||'团队尚未回复，可在这里补充发生时间和变化。')}</div>${field('想补充的情况',textarea('reply-note','','请描述变化或回答团队的问题。'))}<label class="checkbox"><input id="reply-urgent" type="checkbox"><span>情况加重或紧急，需要优先帮助；不要等待线上回复。</span></label><div class="notice red">紧急情况请及时寻求线下帮助，必要时拨打 120。原型不会发出真实通知。</div><h3>跟进记录</h3><div class="audit-list">${item.audit.map(audit=>`<div><small>${escapeHtml(audit.time)}</small><p>${escapeHtml(audit.text)}</p></div>`).join('')}</div>`, '<button class="btn" data-action="close">返回</button><button class="btn primary" data-action="save-reply" data-id="'+id+'">提交补充信息</button>');
}
function saveReply(id){
  const item=state.cases.find(entry=>entry.id===id),urgent=checked('reply-urgent'),note=read('reply-note')||(urgent?'患者标记情况紧急，具体变化待核实。':'');
  if(!item||item.pid!==activePatient().id||item.status==='已关闭')return;
  if(!urgent&&note.length<4)return formError('请至少用 4 个字补充情况；紧急反馈可直接提交。');
  item.status=item.owner==='待认领'?'待处理':'跟进中';if(urgent)item.level='high';item.reviewed=false;
  item.audit.push({time:`10-08 ${timeLabel()}`,text:`患者补充：${note}${urgent?'（标记紧急，提升为高优先级）':''}`});
  item.detail+=`\n患者补充：${note}`;
  addMessage(item.pid,'补充信息已回到原事项','已保留原负责人和处理轨迹，等待医护复核。紧急情况不要等待线上回复。','系统回执','恢复助手');
  addEvent(`${patientById(item.pid).name} · 已补充原事项信息`);persist();closeModal();toast('补充信息已回到原事项，未自动关闭待办');
}
function showModal(title,subtitle,body,footer='',wide=false){
  if(!document.querySelector('.modal'))dialogReturnFocus=document.activeElement;
  document.getElementById('overlay').innerHTML=`<div class="overlay"><section class="modal ${wide?'wide':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1"><header class="modal-head"><div><h2 id="modal-title">${title}</h2><p>${subtitle}</p></div><button class="icon-btn" aria-label="关闭弹窗" data-action="close">${icon('close')}</button></header><div class="modal-body"><div id="form-error" class="validation-error" role="alert"></div>${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;
  document.body.style.overflow='hidden';
  document.querySelector('.modal').focus();
  if(modalContext.kind==='case')restoreCaseDraft();
}
function closeModal(){document.getElementById('overlay').innerHTML='';document.body.style.overflow='';if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();}
function formError(message){const target=document.querySelector('.modal #form-error')||document.getElementById('form-error')||document.getElementById('task-form-error');target.textContent=message;target.classList.add('show');target.scrollIntoView({block:'nearest'});}
function field(label,input,help=''){return `<label class="field"><span>${label}</span>${input}${help?`<small>${help}</small>`:''}</label>`;}
function input(id,value='',type='text',extra=''){return `<input id="${id}" type="${type}" value="${escapeHtml(value)}" ${extra}>`;}
function textarea(id,value='',placeholder=''){return `<textarea id="${id}" placeholder="${escapeHtml(placeholder)}" maxlength="1000">${escapeHtml(value)}</textarea>`;}
function read(id){return document.getElementById(id)?.value.trim()||'';}
function checked(id){return Boolean(document.getElementById(id)?.checked);}
function patientDetail(id){const patient=patientById(id),published=patientHasPublishedPlan(patient);showModal(`${escapeHtml(patient.name)} · 服务档案`,`${escapeHtml(patient.procedure)} / ${escapeHtml(patient.team)} / 虚构患者`, `<div class="detail-grid"><div><div class="detail-block"><h3>档案与授权</h3><p>${patient.age} 岁 · ${patient.gender}<br>入组：${displayDate(patient.created)}<br>本人授权：${patient.consent?'已确认（演示）':'待确认'}<br>服务负责人：${currentClinician}<br>复诊日期：${displayDate(patient.appointment)}</p></div><div class="detail-block"><h3>${published?`当前计划 ${planVersionLabel(patient)}`:'阶段计划尚未建立'}</h3><p>${published?`${escapeHtml(patient.plan.stage)}<br>${enabledTasks(patient).map(type=>serviceTypes[type]).join(' / ')}<br>${escapeHtml(patient.plan.note)}`:'服务档案已完成，下一步由医护从模板或内容库配置计划；发布后才会产生 V1。'}</p><button class="btn ${published?'':'primary'}" style="margin-top:12px" data-action="plan" data-id="${id}">${published?'查看计划与历史版本':'建立阶段计划'} →</button></div></div><div><div class="detail-block"><h3>待跟进事项 · ${openCases(id).length}</h3>${openCases(id).map(item=>`<div class="mini-row"><span>${escapeHtml(item.type)}</span><button class="link" data-action="case" data-id="${item.id}">${escapeHtml(item.status)} →</button></div>`).join('')||'<p>暂无待跟进事项。</p>'}</div><div class="detail-block"><h3>本次演示执行记录</h3>${patientRecords(id).slice(0,4).map(record=>`<p>${record.time} · ${escapeHtml(record.title)}<br><small>${escapeHtml(record.status)} / ${escapeHtml(record.source)} / ${record.version?'V'+record.version:'建档阶段'}</small></p>`).join('')||'<p>尚未新增记录。可切换患者端体验任务提交。</p>'}</div></div></div>`,`<button class="btn" data-action="appointment" data-id="${id}">安排复诊</button><button class="btn primary" data-action="experience" data-id="${id}">以此患者体验</button>`,true);}
function caseDetail(id){
  const item=state.cases.find(entry=>entry.id===id),patient=patientById(item.pid);modalContext={kind:'case',id};
  const closed=item.status==='已关闭';
  showModal('事项详情与处置',`${escapeHtml(patient.name)} · ${escapeHtml(patient.procedure)} · ${escapeHtml(item.created)}`,`<div class="notice ${item.level==='high'?'red':'blue'}"><strong>${escapeHtml(item.title)}</strong><br>${escapeHtml(item.detail)}<br><small>来源：${escapeHtml(item.source)} · 原始线索不等于临床诊断</small></div><div class="between" style="margin-bottom:20px">${sourceTag(item.level==='high'?'高优先级 · 需人工复核':item.level==='medium'?'需要跟进':'常规咨询',item.level==='high'?'red':'orange')}<small>${escapeHtml(item.status)} / ${escapeHtml(item.owner)}</small></div>${closed?`<div class="result-card"><h3>已由 ${escapeHtml(item.owner)} 关闭</h3><p>${escapeHtml(item.resolution)}</p></div>`:`${field('医护点评 / 处置依据',textarea('case-note','','填写已核实的情况、给患者的反馈及下一步安排。此内容会发送到患者消息。'),'不能仅用“已处理”替代明确的处置记录。')}${field('处置后状态',`<select id="case-status"><option value="跟进中">继续跟进</option><option value="待患者补充">待患者补充信息</option><option value="待复诊">待复诊（请先安排日期）</option><option value="已关闭">已解决，人工关闭</option></select>`)}${item.level==='high'?'<label class="checkbox"><input id="case-review" type="checkbox"><span>我已作为授权医护核实该高优先级事项，并记录评估与处置依据。<br><small>关闭前必选；AI和患者确认不能代替此复核。</small></span></label>':''}<div class="flex" style="flex-wrap:wrap"><button class="btn small" data-action="case-plan" data-id="${patient.id}">调整阶段计划</button><button class="btn small" data-action="case-appointment" data-id="${patient.id}">安排复诊</button></div>`}<hr class="rule"><h3>处理轨迹</h3><div class="audit-list">${item.audit.map(audit=>`<div><small>${escapeHtml(audit.time)}</small><p>${escapeHtml(audit.text)}</p></div>`).join('')}</div>`,closed?'<button class="btn" data-action="close">关闭</button>':`<button class="btn" data-action="claim" data-id="${id}" ${item.owner===currentClinician?'disabled':''}>${item.owner===currentClinician?'已由我接管':'由我接管'}</button><button class="btn primary" data-action="save-case" data-id="${id}">保存处置并通知患者</button>`);
}
function saveCase(id){
  const item=state.cases.find(entry=>entry.id===id),note=read('case-note'),status=read('case-status');
  if(item.owner!==currentClinician)return formError('请先点击“由我接管”，明确当前处理责任人。');
  if(note.length<6)return formError('请至少填写 6 个字的具体处置依据和患者反馈。');
  if(status==='已关闭'&&item.level==='high'&&!checked('case-review'))return formError('高优先级事项必须经授权医护复核确认后才能关闭。');
  if(status==='待复诊'&&!state.visits.some(visit=>visit.caseId===id))return formError('请先为本事项安排复诊，再标记为“待复诊”。原有预约不自动视为本次安排。');
  item.status=status;item.resolution=note;item.reviewed=status==='已关闭'&&item.level==='high'?true:item.reviewed;caseDrafts.delete(id);
  item.audit.push({time:`10-08 ${timeLabel()}`,text:`${currentClinician}：${note}。状态更新为${status}${item.reviewed?'，已人工复核':''}。`});
  addMessage(item.pid,`${item.type} · 医护已回应`,note+'（事项状态：'+status+'）','医护确认',currentClinician,{level:item.level,caseId:item.id});addEvent(`${patientById(item.pid).name} · ${currentClinician}已保存处置`);persist();closeModal();toast('处置已保存，患者端“消息”已收到医护回复');
}
function showPlan(id,editable=true,returnCase=null){
  if(editable)return openCareBuilder(id,returnCase);
  const patient=patientById(id);if(!patientHasPublishedPlan(patient))return showModal(`${escapeHtml(patient.name)} · 阶段计划`,'服务档案已建立，当前还没有已发布计划',`<div class="notice blue">下一步由医护从动作库、食材库或常用模板配置内容，完成周期设置和人工核对后发布 V1。</div><p>计划发布前，患者端不会显示具体训练、饮食或随访任务。</p>`,`<button class="btn" data-action="close">稍后再说</button>${ui.role==='doctor'?`<button class="btn primary" data-action="plan" data-id="${id}">进入建立计划</button>`:''}`);
  const plan=patient.plan;
  modalContext={kind:'plan',id};
  const content=Array.isArray(plan.actions)?careContentSummary(plan):`${plan.training?`<p>康复训练：${plan.sets} 组 × ${plan.reps} 次（旧版演示动作）</p>`:''}${plan.nutrition?`<p>饮食记录：能量目标 ${plan.energy} kcal / 蛋白质 ${plan.protein} g（旧版演示）</p>`:''}${plan.survey?'<p>每日恢复随访</p>':''}`;
  showModal('我的阶段计划',`V${plan.version} · ${escapeHtml(plan.author)}确认 · ${displayDate(plan.start)}起生效`,`<div class="notice green">${escapeHtml(plan.stage)}<br>${displayDate(cycleFor(patient).start)} — ${displayDate(plan.end)} · 每 ${cycleFor(patient).reviewEvery||'待设置'} 天回访</div>${content}<p>${escapeHtml(plan.note)}</p><div class="notice">仅为原型演示，不用于真实训练或营养治疗。库更新不会改变这份已发布计划；患者不能自行修改医护计划。</div><h3>已发布版本</h3><div class="audit-list">${patient.versions.slice().reverse().map(version=>`<div><small>V${version.version} · ${displayDate(version.start)} · ${escapeHtml(version.author)}</small><p>${escapeHtml(version.reason)}</p></div>`).join('')}</div>`,`<button class="btn primary" data-action="close">我知道了</button>`);
}
function enroll(){showModal('建立患者服务档案','演示入组 · 请勿输入真实患者信息',`<div class="notice blue">模拟“就诊 / 出院后由医护入组”。本步骤只建立服务档案，不生成计划版本；完成后可进入计划编辑器继续配置。</div><div class="form-row">${field('患者称呼',input('enroll-name','','text','placeholder="如：赵阿姨（虚构）" maxlength="15"'))}${field('年龄',input('enroll-age','60','number','min="18" max="110"'))}</div><div class="form-row">${field('性别','<select id="enroll-gender"><option>女</option><option>男</option></select>')}${field('服务路径', '<select id="enroll-path"><option>康复随访</option><option>营养随访</option><option>检查后随访</option></select>')}</div>${field('就诊 / 出院事项',input('enroll-procedure','','text','placeholder="填写模拟就诊事项" maxlength="60"'))}<div class="notice">建档后患者端显示“等待医护设置阶段计划”，不会提前派发康复训练、饮食记录或恢复随访任务。</div><label class="checkbox"><input id="enroll-consent" type="checkbox"><span>已向患者说明服务范围、时段和数据使用，并取得本人授权（模拟）。</span></label><label class="checkbox"><input id="enroll-confirm" type="checkbox"><span>我已核对入组路径和档案信息，确认先建立服务档案。</span></label>`,`<button class="btn" data-action="close">取消</button><button class="btn primary" data-action="save-enroll">建立服务档案</button>`);}
function saveEnroll(){const name=read('enroll-name'),age=Number(read('enroll-age')),path=read('enroll-path'),procedure=read('enroll-procedure');if(!name||!procedure)return formError('请填写虚构患者称呼和就诊事项。');if(!Number.isInteger(age)||age<18||age>110)return formError('首期演示仅支持 18–110 岁成人档案。');if(!checked('enroll-consent')||!checked('enroll-confirm'))return formError('请确认患者授权及档案信息。');const patient={id:uuid('patient'),name,age,gender:read('enroll-gender'),path,procedure,day:1,color:'blue',team:path==='康复随访'?'康复服务团队':path==='营养随访'?'营养服务团队':'消化内科服务团队',plan:emptyPlan(),versions:[],appointment:null,consent:true,created:TODAY,history:[0,0,0,0,0,0]};state.patients.push(patient);addMessage(patient.id,'服务档案已建立',`欢迎加入${patient.team}。医护接下来会为你设置阶段计划，发布后即可查看长期周期和每日任务。`,'系统通知','服务助手');addEvent(`${name} · 服务档案已建立，等待阶段计划`);ui.patientId=patient.id;ui.page='patients';persist();closeModal();showModal('服务档案已建立','下一步：为患者建立阶段计划',`<div class="notice green">${escapeHtml(patient.name)}的档案已保存，目前尚无计划版本，也不会提前派发每日任务。</div><p>接下来可选择动作与食材、设置周期，医护核对发布后才生成 V1。也可以稍后从患者档案或阶段计划列表继续。</p>`,`<button class="btn" data-action="close">稍后设置</button><button class="btn primary" data-action="plan" data-id="${patient.id}">建立阶段计划</button>`);}
function appointment(id,returnCase=null){const patient=patientById(id);modalContext={kind:'appointment',id,returnCase};showModal('安排复诊',`${escapeHtml(patient.name)} · 当前安排 ${displayDate(patient.appointment)}`,`<div class="notice blue">原型只记录“复诊安排”，不代表医院真实号源预约成功。正式版本需确认挂号衔接规则。</div>${field('复诊日期',input('visit-date',patient.appointment||'2026-10-15','date',`min="${TODAY}" max="2027-12-31"`))}${field('复诊方式','<select id="visit-mode"><option>到院复诊</option><option>线上评估（需确认适用条件）</option></select>')}${field('复诊目的与准备事项',textarea('visit-note','','请说明为什么复诊，以及患者需要准备的资料。'))}`,`<button class="btn" data-action="${returnCase?'case':'close'}" ${returnCase?`data-id="${returnCase}"`:''}>取消</button><button class="btn primary" data-action="save-appointment" data-id="${id}">确认安排并通知患者</button>`);}
function saveAppointment(id){const date=read('visit-date'),note=read('visit-note'),mode=read('visit-mode'),returnCase=modalContext.returnCase;if(!date||date<TODAY||date>'2027-12-31')return formError('请选择有效的复诊日期（不得早于演示日）。');if(note.length<6)return formError('请填写至少 6 个字的复诊目的与准备事项。');const patient=patientById(id);patient.appointment=date;state.visits.push({id:uuid('visit'),pid:id,date,note,mode,caseId:returnCase,author:currentClinician});addMessage(id,'复诊安排已更新',`${displayDate(date)} · ${mode}。${note}。此为模拟安排，不代表真实挂号成功。`);if(returnCase)state.cases.find(item=>item.id===returnCase).audit.push({time:`10-08 ${timeLabel()}`,text:`${currentClinician}安排 ${displayDate(date)} ${mode}：${note}。`});addEvent(`${patient.name} · 已安排 ${displayDate(date)} 复诊`);persist();if(returnCase)caseDetail(returnCase);else closeModal();toast('复诊安排已同步到患者端');}
function training(step='intro',result=null){const patient=activePatient();if(configuredTrainingDeferred(patient))return toast('今日已有旧版本训练记录，新版训练明日起执行，请勿重复补做。');modalContext={kind:'training',step,result};ui.task.result=result;const total=(taskSlot().reps||patient.plan.reps)*taskSlot().sets;if(step==='intro'){showTaskPage('今天的康复训练','跟着示范，按已确认的计划执行',`<div class="notice green">演示训练 · ${escapeHtml(taskSlot().label)} · ${taskSlot().sets} 组 × ${taskSlot().reps||patient.plan.reps} 次<br>${escapeHtml(taskSlot().note||'')}<br>绑定计划 V${patient.plan.version}，仅供交互体验。</div><div class="simulation-stage"><span class="stage-label">示范画面 · 非医疗动作指导</span><svg viewBox="0 0 150 190"><circle cx="75" cy="30" r="14"/><path d="M75 44v59m0-38-35 28m35-28 35 28m-35 10-25 63m25-63 25 63"/><circle cx="75" cy="65" r="4"/><circle cx="75" cy="103" r="4"/><path d="M20 173h110"/></svg></div><p style="font-size:12px;color:#819475;line-height:1.9">实际产品将在这里检查拍摄范围、机位与关键点质量。原型不访问相机，下一步由你选择模拟结果。出现不适请停止，不必完成训练。</p>`,`<button class="btn" data-action="training-discomfort">现在有不适</button><button class="btn primary" data-action="training-start">开始模拟训练</button>`);}else if(step==='running'){showTaskPage('训练进行中 · 模拟','无真实视频采集 / 无真实动作识别',`<div class="simulation-stage"><span class="stage-label">演示关键点 · 已适配机位</span><svg viewBox="0 0 150 190"><circle cx="75" cy="30" r="14"/><path d="M75 44v59m0-38L25 43m50 22 50-22m-50 60-25 63m25-63 25 63"/><circle cx="75" cy="65" r="4"/><circle cx="75" cy="103" r="4"/><circle cx="25" cy="43" r="4"/><circle cx="125" cy="43" r="4"/></svg><div class="stage-count">${Math.max(1,total-3)}<small> / ${total} 次</small></div><span class="stage-label bottom">正在模拟训练过程</span></div><div class="radio-options"><label><input type="radio" name="train-result" value="normal" checked>动作可评估，模拟完成全部次数</label><label><input type="radio" name="train-result" value="unavailable">画面遮挡 / 机位失败，无法评估</label></div><div class="notice">无法评估时不生成有效次数或成功结论，可降级为患者自报。</div>`,`<button class="btn danger" data-action="training-discomfort">停止并反馈不适</button><button class="btn primary" data-action="training-result">查看模拟结果</button>`);}else{const unavailable=result==='unavailable';showTaskPage('确认训练记录','AI结果需要确认；原始模拟结果与患者更正分别保留',`<div class="result-card"><h3>${unavailable?'画面质量不足 · 无法评估':`模拟识别：${total} 次 / ${taskSlot().sets} 组`}</h3><p>${unavailable?'本次没有可信计次，不计为AI确认完成。可补充自己实际完成的情况。':'只对已适配动作提供计次反馈，不代表医学评估或康复效果。'}</p></div>${field('你实际完成了多少次？',input('train-actual',unavailable?'0':total,'number','min="0" max="150"'),'患者自报与AI模拟结果分别保存。')}${field('补充说明（可选）',textarea('train-note','','例如：中途休息了一会儿'))}<label class="checkbox"><input id="train-confirm" type="checkbox"><span>我已核对本次记录。如有不适，请点击下方停止并反馈。</span></label>`,`<button class="btn" data-action="training-discomfort">有不适，停止反馈</button><button class="btn primary" data-action="save-training">确认并保存</button>`);}}
function saveTraining(){if(configuredTrainingDeferred(activePatient()))return toast('计划已更新，请勿重复训练。');const patient=activePatient(),actual=Number(read('train-actual')),unavailable=ui.task.result==='unavailable';if(!Number.isInteger(actual)||actual<0||actual>150)return formError('请填写 0–150 的整数次数。');if(!checked('train-confirm'))return formError('请核对后勾选确认。');const note=read('train-note');addRecord(patient.id,'training','康复训练记录',`${unavailable?'AI模拟：无法评估':'AI模拟：'+(taskSlot().reps||patient.plan.reps)*taskSlot().sets+'次'}；患者确认：${actual}次。${note}`,unavailable?'不可评估':actual>=(taskSlot().reps||patient.plan.reps)*taskSlot().sets?'已完成':'部分完成',unavailable?'患者自报 / AI不可评估':'AI模拟 + 患者确认');finishPatientTask();toast(unavailable?'记录已保存为不可评估，不计入有效完成':'训练记录已保存');}
function discomfort(origin='主动反馈'){
  modalContext={kind:'discomfort',origin};
  showModal('停止当前任务，先关注你的感受','不用等到训练结束再反馈',`<div class="notice red"><strong>若症状严重或有紧急危险，请立即寻求线下紧急帮助。</strong><br>此处不是急救通道，请不要等待线上回复。必要时拨打 120。</div>${field('请描述发生了什么',textarea('discomfort-note','','例如：训练过程中突然感到明显不适，已经停止。'))}<label class="checkbox"><input id="discomfort-urgent" type="checkbox"><span>我认为情况紧急，希望优先获得人工帮助。<br><small>这会生成高优先级事项，但不代表有人实时值守。</small></span></label><p class="muted" style="font-size:11px;line-height:1.8">提交即保存并进入医护队列，不经过“确认AI结果”步骤。原型不会拨打电话或发送真实通知。</p>`,`<button class="btn" data-action="close">暂不提交</button><button class="btn danger" data-action="save-discomfort">提交不适，通知团队</button>`);
}
function saveDiscomfort(){const urgent=checked('discomfort-urgent'),note=read('discomfort-note')||(urgent?'患者标记紧急不适，具体情况待医护核实。':'');if(!urgent&&note.length<4)return formError('请至少用 4 个字描述不适情况。紧急情况可勾选优先帮助后直接提交。');const patient=activePatient(),origin=modalContext.origin;addRecord(patient.id,origin==='训练'?'training':'survey',`${origin} · 不适反馈`,note,'因不适停止','患者自报');const item=addCase(patient.id,origin==='训练'?'训练不适':'主动不适反馈',urgent?'high':'medium','患者报告不适，需要人工了解',note);addMessage(patient.id,'不适反馈已收到',`事项已进入${item.level==='high'?'高优先级':'人工'}队列，等待团队接管。若情况紧急，请及时寻求线下帮助，不要等待回复。`,'系统回执','恢复助手');persist();showModal('反馈已收到','已保存原始自报，等待医护接管',`<div class="notice red">紧急情况请及时就医，必要时拨打 120，不要等待线上回复。</div><div class="result-card"><h3>${escapeHtml(item.status)} · ${item.level==='high'?'高优先级':'人工跟进'}</h3><p>${escapeHtml(note)}<br>当前负责人：${escapeHtml(item.owner)}</p></div><p class="muted" style="font-size:12px;line-height:1.9">工作日 08:00—17:00 为演示服务时段。真实响应时限与值班制度需由院方确认。</p>`,`<button class="btn" data-action="close">返回患者端</button><button class="btn primary" data-action="go-case" data-id="${item.id}">演示：去医护端处理</button>`);}
function nutrition(step='intro'){
  modalContext={kind:'nutrition',step};
  if(step==='intro'){showTaskPage('记录这一餐','拍照是入口，真正吃下的部分才是记录',`<div class="food-visual"><div class="plate"></div><p>演示餐盘<br>米饭 · 鸡肉 · 青菜</p></div><div class="notice">不访问相机或上传照片。点击后载入预设识别候选，也可以直接手动填写。</div><p class="muted" style="font-size:12px;line-height:1.9">不承诺照片精确测重；原型仅演示份量确认与医护跟进。库外食物可以记录，但不强行计算营养值。</p>`,`<button class="btn" data-action="nutrition-manual">手动记录</button><button class="btn primary" data-action="nutrition-result">模拟拍照识别</button>`);return;}
  const manual=step==='manual';showTaskPage('确认食物与实食量',manual?'手动记录 · 可注明库外食物':'AI候选仅供核对，不会自动保存',`<div class="food-visual"><div class="plate"></div><p>${manual?'手动补充餐食':'AI模拟候选'}<br>需确认食物和份量</p></div>${field('食物 / 餐食名称',input('meal-name',manual?'':'米饭 + 鸡肉 + 青菜','text','maxlength="60"'))}${field('估算方式','<select id="meal-library"><option value="standard">演示标准套餐：约 600 kcal / 30 g蛋白质（每份）</option><option value="unknown">库外食物：仅保存描述，不计算营养</option></select>')}<div class="form-row">${field('上桌份量','<select id="meal-serving"><option value="0.5">半份</option><option value="1" selected>1 份</option><option value="1.5">1.5 份</option><option value="2">2 份</option></select>')}${field('实际吃下比例','<select id="meal-eaten"><option value="1">全部</option><option value="0.75">约四分之三</option><option value="0.5">约一半</option><option value="0.25">约四分之一</option><option value="0">没有吃下</option></select>')}</div>${field('补充说明（可选）',textarea('meal-note','','例如：鸡肉剩下一半，份量只能大致估计'))}<label class="checkbox"><input id="meal-confirm" type="checkbox"><span>我已核对食物、份量及实食比例，理解营养值是估算而非精确测量。</span></label><div class="notice">演示规则：实食比例≤25%时提示人工核实；这不是临床标准，也不会诊断营养不良。</div>`,`<button class="btn" data-action="task-overview">取消</button><button class="btn primary" data-action="save-nutrition">确认这一餐</button>`);
  if(manual)document.getElementById('meal-library').value='unknown';
}
function saveNutrition(){const name=read('meal-name'),serving=Number(read('meal-serving')),eaten=Number(read('meal-eaten')),unknown=read('meal-library')==='unknown',note=read('meal-note');if(!name)return formError('请填写实际食物或餐食名称。');if(!checked('meal-confirm'))return formError('请核对食物和实食量后勾选确认。');const patient=activePatient(),detail=`${name}，${serving}份 × 实食${eaten*100}%。${unknown?'库外食物，不估算营养。':`估算 ${Math.round(600*serving*eaten)} kcal / ${Math.round(30*serving*eaten)} g蛋白质。`}${note}`;addRecord(patient.id,'nutrition','饮食记录',detail,'已完成',unknown?'患者自报 / 营养不可估算':'患者确认 / 营养估算');if(eaten<=0.25){addCase(patient.id,'摄入待核实','medium','患者记录进食偏少，需要核实',detail,'演示规则 + 患者确认');addMessage(patient.id,'饮食记录已提交团队核实','这次记录的进食比例偏低，已提交服务团队了解。单次记录不用于判断营养状态。','系统回执','恢复助手');}finishPatientTask();toast(eaten<=0.25?'已保存，并生成一项人工核实待办':'饮食记录已保存，营养估算不会自动改变计划');}
function survey(){modalContext={kind:'survey'};showTaskPage('今天恢复得怎么样？','3 个小问题 · 约 1 分钟',`<h3>1. 今天有没有想反馈的不适？</h3><div class="radio-options"><label><input type="radio" name="survey-feeling" value="normal" checked>没有新增不适，希望继续按计划执行</label><label><input type="radio" name="survey-feeling" value="concern">有些不适，想请团队进一步了解</label><label><input type="radio" name="survey-feeling" value="urgent">有明显或紧急不适，需要优先帮助</label></div>${field('2. 今天执行计划是否遇到困难？','<select id="survey-barrier"><option value="none">没有明显困难</option><option value="unclear">不清楚怎么完成任务</option><option value="unable">身体或设备原因，暂时无法完成</option></select>')}${field('3. 还有什么想告诉团队？',textarea('survey-note','','可描述发生时间、变化和需要的帮助。'))}<div id="survey-safety" class="notice red" hidden>若情况紧急，请及时线下就医，必要时拨打 120，不要等待线上回复。选择本项不构成诊断。</div><div class="notice">不适描述直接进入人工复核流程；“没有新增不适”不会关闭既有高风险事项。</div>`,`<button class="btn" data-action="task-overview">稍后填写</button><button class="btn primary" data-action="save-survey">提交今天的反馈</button>`);}
function saveSurvey(){const feeling=document.querySelector('input[name="survey-feeling"]:checked').value,barrier=read('survey-barrier'),note=read('survey-note');if(feeling==='concern'&&note.length<4)return formError('请在第 3 题至少用 4 个字补充不适情况，便于团队了解。');const patient=activePatient(),detail=`${feeling==='normal'?'无新增不适':feeling==='urgent'?'患者报告明显或紧急不适':'患者报告不适'}；执行困难：${{none:'无',unclear:'任务不清楚',unable:'暂无法完成'}[barrier]}。${note}`;addRecord(patient.id,'survey','恢复问答记录',detail,'已完成','患者自报');let item;if(feeling!=='normal')item=addCase(patient.id,'恢复不适反馈',feeling==='urgent'?'high':'medium','恢复问答中报告不适',detail);else if(barrier!=='none')item=addCase(patient.id,'任务执行困难','normal','患者需要执行帮助',detail);if(item)addMessage(patient.id,'恢复反馈已进入医护队列',`${item.title}。团队将在服务时段跟进；紧急情况请及时就医，不等待回复。`,'系统回执','恢复助手');persist();if(feeling==='urgent'){showTaskPage('已提交高优先级事项','请不要等待线上回复才寻求紧急帮助',`<div class="notice red">若症状严重或有紧急危险，请立即寻求线下紧急帮助，必要时拨打 120。此原型不会发出真实通知。</div><div class="result-card"><h3>医护队列已收到反馈</h3><p>${escapeHtml(detail)}</p></div>`,`<button class="btn" data-action="task-overview">我知道了</button><button class="btn primary" data-action="go-case" data-id="${item.id}">演示：查看医护事项</button>`);}else{finishPatientTask();toast(item?'已提交，团队将进一步跟进':'反馈已保存，既有待办不会自动关闭');}}
function ask(){modalContext={kind:'ask'};showModal('恢复助手','演示固定问答 · 不是开放式AI问诊',`<div class="notice green">先帮助你找到院方服务说明。超出已审核内容的问题，会转给人工团队，不猜测答案。</div>${field('你想了解什么？','<select id="ask-topic"><option value="tasks">在哪里查看今天的任务？</option><option value="response">团队什么时候回复？</option><option value="visit">如何查看复诊安排？</option><option value="other">其他问题 / 想请医护帮助</option></select>')}${field('补充问题（选“其他”时必填）',textarea('ask-note','','请勿填写真实身份信息。'))}<button class="link flex" data-action="discomfort">${icon('alert')}身体不适？使用专门的反馈入口</button>`,`<button class="btn" data-action="close">取消</button><button class="btn primary" data-action="save-ask">发送</button>`);}
function saveAsk(){const topic=read('ask-topic'),note=read('ask-note'),patient=activePatient();if(topic==='other'&&note.length<4)return formError('请至少填写 4 个字的问题描述。');let reply;if(topic==='other'||note){addCase(patient.id,'恢复咨询','normal','患者咨询需要人工回复',note||'患者请求医护帮助','患者提问');reply='您的问题已交给服务团队。原型助手不会对未审核的问题或个体诊疗问题生成答案。';}else reply={tasks:'打开“今日”即可查看当前医护计划下的任务。每项完成后请核对并确认记录。',response:'演示服务时段为工作日 08:00—17:00；不代表全天实时监护。紧急情况请及时就医，不要等待回复。',visit:`您的模拟复诊日期为 ${displayDate(patient.appointment)}，可在“我的”查看。此为安排记录，不代表号源已预约。`}[topic];addMessage(patient.id,'恢复助手回复',reply,'审核内容 / 固定演示','恢复助手');addEvent(`${patient.name} · 已提交恢复咨询`);ui.patientPage='messages';persist();closeModal();toast(topic==='other'||note?'问题已转交人工团队':'已使用预设服务说明回复');}
function reportData(id){const patient=patientById(id),records=patientRecords(id),completed=(patient.history||[]).reduce((total,value)=>total+value,0)+completedToday(patient);return {id:uuid('report'),pid:id,created:`10-08 ${timeLabel()}`,version:patient.plan.version,completed,todayCompleted:completedToday(patient),todayTasks:enabledTasks(patient).length,records:JSON.parse(JSON.stringify(records)),cases:JSON.parse(JSON.stringify(patientCases(id))),appointment:patient.appointment,reviewed:false,reviewNote:'',history:[...(patient.history||[]),completedToday(patient)]};}
function reportBody(patient,report){const pending=report.cases.filter(item=>item.status!=='已关闭'),closed=report.cases.filter(item=>item.status==='已关闭');return `<div class="notice ${report.reviewed?'green':'blue'}">${report.reviewed?`医护已复核 · ${escapeHtml(report.reviewer)} · ${escapeHtml(report.reviewTime)}`:'AI整理草稿（模拟），尚未经医护复核'}<br>快照 ${escapeHtml(report.created)} · ${report.version?`绑定计划 V${report.version}`:'尚未建立阶段计划'} · 不输出恢复诊断</div><div class="report-grid" style="margin:20px 0 28px"><div><strong>${report.completed}</strong><small>本周完成任务次数</small></div><div><strong>${pending.length}</strong><small>未解决事项</small></div><div><strong>${closed.length}</strong><small>已人工关闭事项</small></div></div><div class="detail-block"><h3>01 / 执行与数据来源</h3><p>10.02—10.07为预置历史汇总，共 ${report.history.slice(0,6).reduce((sum,value)=>sum+value,0)} 次。今日完成 ${report.todayCompleted} / ${report.todayTasks} 项，为本地已确认记录。<br>未完成或缺失数据不能推断为恢复正常。营养数值为估算，动作数据仅为模拟。</p>${report.records.slice(0,6).map(record=>`<p style="margin-top:10px">${escapeHtml(record.title)} · ${escapeHtml(record.status)}<br><small>${escapeHtml(record.source)} / ${record.version?`计划 V${record.version}`:'建档后反馈 · 暂无计划'} / ${record.time}</small></p>`).join('')}</div><div class="detail-block"><h3>02 / 待跟进与已处置事项</h3>${report.cases.map(item=>`<p style="margin-bottom:9px">${escapeHtml(item.type)} · ${escapeHtml(item.status)}<br><small>${escapeHtml(item.resolution||'待医护进一步了解，不作临床结论。')}</small></p>`).join('')||'<p>暂无事项记录；不代表已完成临床评估。</p>'}</div><div class="detail-block"><h3>03 / 下次复诊待讨论</h3><p>安排日期：${displayDate(report.appointment)}（非真实挂号）<br>${pending.length?pending.map(item=>escapeHtml(item.title)).join('<br>'):'请与医护核对当前计划和下一阶段安排。'}</p></div>${report.reviewed?`<div class="detail-block"><h3>医护复核意见</h3><p>${escapeHtml(report.reviewNote)}</p></div>`:''}`;}
function reportModal(id,patientView=false,regenerate=false){const patient=patientById(id);let report=state.reports.find(item=>item.pid===id);if(!report||regenerate){report=reportData(id);state.reports=state.reports.filter(item=>item.pid!==id);state.reports.unshift(report);persist();}modalContext={kind:'report',id,reportId:report.id};showModal(`${escapeHtml(patient.name)} · 恢复周报`,'2026.10.02 — 2026.10.08 · 复诊摘要，不是诊断报告',`${reportBody(patient,report)}${!patientView&&!report.reviewed?`${field('医护复核意见',textarea('report-note','','核对数据与未解决事项，填写需要带到复诊的问题。'))}<label class="checkbox"><input id="report-confirm" type="checkbox"><span>已核对数据来源、缺失情况及高优先级事项状态，确认向患者发布该摘要。</span></label>`:''}`,patientView?'<button class="btn primary" data-action="close">返回</button>':`<button class="btn" data-action="regenerate-report" data-id="${id}">用当前记录重新生成</button>${report.reviewed?'<button class="btn primary" data-action="close">完成</button>':`<button class="btn primary" data-action="review-report" data-id="${id}">医护确认并发布</button>`}`);}
function reviewReport(id){const report=state.reports.find(item=>item.pid===id);if(!checked('report-confirm')||read('report-note').length<6)return formError('请填写至少 6 个字的复核意见，并确认已核对数据。');report.reviewed=true;report.reviewNote=read('report-note');report.reviewer=currentClinician;report.reviewTime=`10-08 ${timeLabel()}`;addMessage(id,'本周恢复摘要已由医护复核',report.reviewNote+'。请在“进度”查看完整周报。');addEvent(`${patientById(id).name} · 周报已复核发布`);persist();reportModal(id);toast('已发布医护确认周报，未解决事项保持原状态');}
function guide(){showModal('用 6 条路径，走查服务闭环','所有操作共享同一份本地模拟数据，可随时重置',`<div class="notice green">建议先以林阿姨体验患者任务，再切换医护工作台处理。任何模拟识别都不调用真实AI，不会发送真实医疗消息。</div><div class="walkthrough">${[
 ['01','建档与入组','医护建立虚构档案 → 确认路径与授权 → 发布 V1 → 患者看到每日任务。','enroll','建立服务档案'],
 ['02','正常执行','患者模拟训练 → 核对次数 → 保存 → 工作台与进度同步新增记录。','guide-training','体验康复训练'],
 ['03','异常闭环','问答选择紧急不适 → 先显示求助指引 → 提交高优先级事项 → 医护接管与复核。','guide-survey','体验恢复随访'],
 ['04','饮食核实','记录餐食并修正实食比例 → 吃下≤25%触发演示待办 → 医护核实反馈。','guide-nutrition','体验饮食记录'],
 ['05','计划与复诊','医护手动发布新版本或安排复诊 → 患者收到消息 → 旧记录保留原版本。','guide-plan','调整林阿姨计划'],
 ['06','复诊摘要','生成当前记录快照 → 医护核对并发布 → 患者看到来源、缺失和待解决事项。','guide-report','查看林阿姨周报']
 ].map(([number,title,detail,action,label])=>`<section class="walk-card"><span class="eyebrow">PATH ${number}</span><h3>${title}</h3><p>${detail}</p><button class="btn small" data-action="${action}">${label} →</button></section>`).join('')}</div><hr class="rule"><h3>务必测试的三个“不能”</h3><p class="muted" style="font-size:12px;line-height:2;margin-top:12px">① 不勾人工复核，不能关闭高优先级事项。<br>② 患者填“无新增不适”，既有事项不能自动关闭。<br>③ 模拟画面不可评估，不能给出成功识别或有效计次。</p>`,`<button class="btn" data-action="issues">查看待细化问题</button><button class="btn primary" data-action="close">开始自由体验</button>`,true);}
function issues(){showModal('下一轮需要细化的业务规则','这些是显式的原型假设，不是已确认的院方规则',`<div class="issue-list">${[
 ['上线前确认','服务责任与排班','谁首接、谁能关闭高风险、跨科如何转交、超时谁兜底？原型仅模拟一名授权医师，不代表真实全天监护。'],
 ['上线前确认','临床路径与安全规则','具体术种、分阶段任务、禁忌与停止条件由院方审核。检后随访和术后康复不能共用一套风险规则。'],
 ['交互待评审','任务调整后如何计算完成','原型保留历史记录的计划版本，但不因当天改计划而重置已确认完成状态。需确认是否补任务、何时生效及避免重复训练。'],
 ['交互待评审','患者确认与记录更正','当前支持提交前修正；提交后更正、撤回及医护修正的双向确认流程需下一版补齐，不能覆盖原始证据。'],
 ['交互待评审','未回复与家庭协助','真实提醒、重试次数、短信/电话兜底、家属授权和退出服务尚未接入。不能默认“未回复即正常”。'],
 ['交互待评审','复诊与线上诊疗','“安排复诊”不等于号源锁定，需确认挂号入口、支付、确认/改期流程，以及线上评估的适用范围。'],
 ['交互待评审','周报发布和版本','本版为单份最新快照，更新会替换旧草稿/周报；正式产品应保留历史版本并区分草稿、医护已发布和患者已读。'],
 ['产品范围','算法与真实数据接入','相机、动作识别、餐食识别、自动语义风险识别、真实推送、身份权限、医院接口均不在此原型范围内。自由文本不做隐式临床判断。']
 ].map(([level,title,detail])=>`<article class="issue-item">${sourceTag(level,level==='上线前确认'?'orange':'blue')}<h3>${title}</h3><p>${detail}</p></article>`).join('')}</div>`,`<button class="btn" data-action="guide">回到流程走查</button><button class="btn primary" data-action="close">继续体验</button>`,true);}
function service(){showModal('服务与数据说明','原型服务规则，不构成真实医疗服务',`<div class="detail-block"><h3>我们在这里做什么</h3><p>协助记录计划执行、整理恢复反馈和联络团队。AI不自动诊断、不自动改处方、不自动关闭高风险事项。</p></div><div class="detail-block"><h3>响应与紧急帮助</h3><p>演示时段：工作日 08:00—17:00。非实时监护，也不是急救通道。紧急情况请及时寻求线下帮助，必要时拨打 120。</p></div><div class="detail-block"><h3>数据保存在哪里</h3><p>所有数据仅保存在当前浏览器的本地存储。不访问相机、麦克风，不上传健康数据，不接入服务端。重置演示会清除本原型内的修改，不影响其他项目资料。</p></div><div class="notice">真实产品的家属授权、代理填写、退出服务与数据权利申请，需要单独设计。此处没有用一个“已同意”按钮冒充完整授权流程。</div>`,`<button class="btn primary" data-action="close">我知道了</button>`);}
document.addEventListener('click',event=>{
  const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
  const action=button.dataset.action,value=button.dataset.value,id=button.dataset.id;
  if(action==='cycle-segment'){const patient=activePatient(),index=Number(value);if(!Number.isInteger(index))return;ui.cycleSelection={key:`${patient.id}:${patient.plan.version}`,index};render();return;}
  if(['claim','case-plan','case-appointment','close'].includes(action))rememberCaseDraft();
  if(action==='reply-case')return replyCase(id);
  if(action==='save-reply')return saveReply(id);
  if(action==='role'){careReadDraft();ui.role=value;location.hash=value;closeModal();render();return;}
  if(action==='page'){careReadDraft();ui.page=value;ui.search='';render();return;}
  if(action==='patient-page'){ui.patientPage=value;if(value==='messages')state.messages.filter(message=>message.pid===activePatient().id).forEach(message=>message.read=true);persist();return;}
  if(action==='filter'){ui.filter=value;render();return;}
  if(action==='close'){closeModal();return;}
  if(action==='guide')return guide();
  if(action==='issues')return issues();
  if(action==='service')return service();
  if(action==='patient-detail')return patientDetail(id);
  if(action==='enroll')return enroll();
  if(action==='save-enroll')return saveEnroll();
  if(action==='case')return caseDetail(id);
  if(action==='claim'){const item=state.cases.find(entry=>entry.id===id);item.owner=currentClinician;item.status='跟进中';item.audit.push({time:`10-08 ${timeLabel()}`,text:`${currentClinician}认领并接管事项。`});addMessage(item.pid,'服务团队已接管反馈',`${currentClinician}已接管“${item.type}”事项，将进一步核实。`,'医护确认',currentClinician,{level:item.level,caseId:item.id});persist();caseDetail(id);toast('已明确责任人，开始跟进');return;}
  if(action==='save-case')return saveCase(id);
  if(action==='plan')return showPlan(id);
  if(action==='view-plan')return showPlan(id,false);
  if(action==='case-plan')return showPlan(id,true,modalContext.id);
  if(action==='save-plan')return carePublish();
  if(action==='appointment')return appointment(id);
  if(action==='case-appointment')return appointment(id,modalContext.id);
  if(action==='save-appointment')return saveAppointment(id);
  if(action==='appointment-info'){const patient=patientById(id);return showModal('下次复诊安排',`${escapeHtml(patient.name)} · 模拟服务安排`,`<div class="result-card"><h3>${displayDate(patient.appointment)}</h3><p>请携带执行记录和恢复周报。<br>此日期为演示安排，并未实际挂号。<br>${escapeHtml(state.visits.filter(visit=>visit.pid===id).at(-1)?.note||'具体准备事项请与服务团队确认。')}</p></div>`,'<button class="btn primary" data-action="close">我知道了</button>');}
  if(action==='experience'){ui.patientId=id;ui.role='patient';ui.patientPage='home';location.hash='patient';closeModal();render();return;}
  if(action==='go-case'){ui.role='doctor';ui.page='overview';location.hash='doctor';render();caseDetail(id);return;}
  if(action==='switch-patient'){return showModal('切换演示患者','各档案计划、消息和事项相互隔离',state.patients.map(patient=>`<button class="task-card" data-action="experience" data-id="${patient.id}">${avatar(patient)}<div><h3>${escapeHtml(patient.name)}</h3><p>${escapeHtml(patient.procedure)}</p></div><span class="arrow">${icon('arrow')}</span></button>`).join(''));}
  if(action==='task')return openPatientTask(value);
  if(action==='task-slot')return startTaskSlot(value);
  if(action==='task-overview'){ui.task.body=null;ui.task.slot=null;render();return;}
  if(action==='dismiss-feedback'||action==='view-feedback'){const message=state.messages.find(entry=>entry.id===id&&entry.pid===activePatient().id);if(!message)return;message.dismissed=true;if(action==='view-feedback'){message.read=true;ui.feedbackId=id;ui.patientPage='feedback';}persist();return;}
  if(action==='training-start')return training('running');
  if(action==='training-result')return training('result',document.querySelector('input[name="train-result"]:checked').value);
  if(action==='save-training')return saveTraining();
  if(action==='training-discomfort')return discomfort('训练');
  if(action==='discomfort')return discomfort();
  if(action==='save-discomfort')return saveDiscomfort();
  if(action==='nutrition-result')return nutrition('result');
  if(action==='nutrition-manual')return nutrition('manual');
  if(action==='save-nutrition')return saveNutrition();
  if(action==='save-survey')return saveSurvey();
  if(action==='ask')return ask();
  if(action==='save-ask')return saveAsk();
  if(action==='report')return reportModal(id);
  if(action==='patient-report')return reportModal(id,true);
  if(action==='regenerate-report'){return showModal('重新生成当前快照？','本版只保留每位患者的最新一份周报',`<div class="notice">重新生成会替换当前周报，并恢复为“未复核草稿”。已发布状态不会继承，原始执行记录和事项不会删除。</div>`,`<button class="btn" data-action="report" data-id="${id}">取消</button><button class="btn primary" data-action="confirm-regenerate" data-id="${id}">确认重新生成</button>`);}
  if(action==='confirm-regenerate')return reportModal(id,false,true);
  if(action==='review-report')return reviewReport(id);
  if(action.startsWith('guide-')){ui.patientId='p1';closeModal();if(['guide-training','guide-nutrition','guide-survey'].includes(action)){ui.role='patient';ui.patientPage='home';render();return openPatientTask(action.replace('guide-',''));}ui.role='doctor';render();return action==='guide-plan'?showPlan('p1'):reportModal('p1');}
  if(action==='reset')return showModal('重置演示数据？','只影响当前原型，不修改项目参考资料',`<p style="font-size:13px;line-height:1.9;color:#7e9177">新增档案、执行记录、点评、计划版本、周报、商品、订单及支付模拟设置会清除，恢复为最初的 4 位虚构患者。此操作不能撤回。</p>`,`<button class="btn" data-action="close">保留当前演示</button><button class="btn danger" data-action="confirm-reset">确认重置</button>`);
  if(action==='confirm-reset'){shopUi={category:'全部',search:'',orderFilter:'全部',orderSearch:'',productId:null,orderId:null};caseDrafts.clear();careUi={identity:'clinician',library:'actions',search:'',draft:null,pickerCategory:'all',currentSlot:'morning',currentMeal:'breakfast'};state=seedState();ui={role:ui.role,page:'overview',patientPage:'home',patientId:'p1',filter:'all',search:''};persist();closeModal();toast('已恢复初始演示数据');}
});
document.addEventListener('input',event=>{if(event.target.id==='case-search'){ui.search=event.target.value;document.getElementById('case-table').innerHTML=caseTable();}});
document.addEventListener('change',event=>{if(event.target.name==='survey-feeling'){document.getElementById('survey-safety').hidden=event.target.value!=='urgent';}});
document.addEventListener('keydown',event=>{const modal=document.querySelector('.modal');if(!modal)return;if(event.key==='Escape')closeModal();if(event.key==='Tab'){const targets=Array.from(modal.querySelectorAll('button:not(:disabled),input:not(:disabled),select:not(:disabled),textarea:not(:disabled),a[href]')).filter(target=>target.offsetParent!==null);const first=targets[0],last=targets.at(-1);if(event.shiftKey&&(document.activeElement===first||document.activeElement===modal)){event.preventDefault();last?.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first?.focus();}}});
window.addEventListener('storage',event=>{if(event.key===STORE_KEY){state=loadState();if(!state.patients.some(patient=>patient.id===ui.patientId))ui.patientId=state.patients[0].id;closeModal();render();toast('另一窗口更新了模拟数据，页面已同步');}});
window.addEventListener('hashchange',()=>{if(['#patient','#doctor'].includes(location.hash)){ui.role=location.hash.slice(1);render();}});
render();
